	/// `POST /restore-credentials`
	pub async fn restore_credentials(&self, body: &RestoreCredentialsArgs) -> crate::Result<RestoreCredentials> {
		self.call_json(::http::Method::POST, "/restore-credentials", Some(body)).await
	}
